import subprocess
import os
import glob
import time
def task_func(test_dir):
    script_times = {}
    python_files = glob.glob(os.path.join(test_dir, "*.py"))

    for script in python_files:
        start_time = time.time()
        try:
            subprocess.run(['python', script], check=True)
            end_time = time.time()
            script_times[os.path.basename(script)] = end_time - start_time
        except subprocess.CalledProcessError:
            script_times[os.path.basename(script)] = None

    return script_times

