import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero.")

    logs = []
    start_time = time.time()
    system = platform.system()

    while time.time() - start_time < duration:
        try:
            if system == "Windows":
                cmd = ["wmic", "cpu", "get", "loadpercentage"]
                output = subprocess.check_output(cmd, shell=True).decode().split('\n')[1].strip()
            else:
                cmd = ["grep", "cpu", "/proc/stat"]
                output = subprocess.check_output(cmd, shell=True).decode().split()[1:5]
                output = str(sum(int(x) for x in output))

            logs.append({
                "timestamp": time.time(),
                "cpu_usage": output
            })
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(logs, f)
        return LOGFILE_PATH
    except IOError:
        return None

