import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    proc = subprocess.Popen(['/bin/bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    ps_proc = psutil.Process(proc.pid)

    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()

    try:
        while proc.poll() is None:
            if time.time() - start_time > timeout:
                for child in ps_proc.children(recursive=True):
                    child.terminate()
                proc.terminate()
                break

            cpu_usage += ps_proc.cpu_percent(interval=0.1)
            mem_usage += ps_proc.memory_info().rss
            time.sleep(0.1)
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        pass

    return {
        'CPU Usage': cpu_usage,
        'Memory Usage': mem_usage
    }

